<!doctype html>
<html lang="vi">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Bản đồ tri thức · Cổng quản trị</title>
<style>
:root{font-family:Inter,system-ui,sans-serif;color:#263244;background:#f8fafc}*{box-sizing:border-box}body{margin:0}button,input{font:inherit}button{cursor:pointer}header{height:76px;background:#fff;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;padding:0 28px;gap:18px}h1{font-size:20px;margin:0;font-weight:700}h2{font-size:15px;margin:0 0 14px}p{line-height:1.55}.muted{color:#66758a}.eyebrow{text-transform:uppercase;letter-spacing:.1em;font-size:11px;font-weight:700;color:#a15b12}.back{color:#a15b12;text-decoration:none;font-size:13px;font-weight:600}.summary{font-size:12px;color:#66758a;margin-top:3px}.workspace{display:grid;grid-template-columns:minmax(580px,1fr) 360px;gap:16px;padding:16px;height:calc(100vh - 76px);min-height:650px}.panel,.canvas-card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;box-shadow:0 1px 3px #12223a0a;overflow:hidden}.panel{padding:18px;overflow:auto}.search{width:100%;border:1px solid #d2d9e2;border-radius:9px;padding:11px 12px;outline:none}.search:focus{border-color:#d89536;box-shadow:0 0 0 3px #f4d6a477}.result-count{font-size:12px;color:#66758a;margin:12px 0}.result{display:block;width:100%;text-align:left;border:1px solid transparent;background:none;border-radius:9px;padding:10px;color:#263244;line-height:1.35}.result:hover,.result.active{background:#fff7eb;border-color:#f1d4aa}.result strong{display:block;font-size:12px;color:#a15b12;margin-bottom:3px}.result span{font-size:13px}.list{max-height:calc(100% - 115px);overflow:auto}.canvas-card{position:relative;background:#fbfcfe;grid-column:1;grid-row:1}.canvas-head{height:65px;border-bottom:1px solid #edf0f4;display:flex;align-items:center;justify-content:space-between;padding:0 18px}.canvas-head h2{margin:0}.sub{font-size:12px;color:#66758a;margin-top:4px}.canvas-actions{display:flex;gap:7px}.small-btn{border:1px solid #dce2ea;background:#fff;border-radius:7px;padding:6px 10px;color:#34445b}.small-btn:hover{background:#f6f8fb}#graph{width:100%;height:calc(100% - 119px);display:block;touch-action:none;cursor:grab}#graph.dragging{cursor:grabbing}.canvas-foot{height:54px;border-top:1px solid #edf0f4;display:flex;align-items:center;gap:13px;padding:0 16px;overflow:auto;white-space:nowrap;font-size:11px;color:#52647b}.swatch{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.graph-edge{stroke-width:1.5;opacity:.45;transition:opacity .2s,stroke-width .2s}.graph-edge.highlight{stroke-width:3;opacity:1}.graph-edge.dim{opacity:.08}.graph-node.dim{opacity:.2}.graph-node.connected circle{stroke:#334155;stroke-width:3}.graph-node{cursor:pointer}.graph-node circle{stroke:#fff;stroke-width:3;filter:drop-shadow(0 3px 5px #26324433)}.graph-node:hover circle,.graph-node.active circle{stroke:#273449;stroke-width:3}.graph-label{font-size:11px;font-weight:600;fill:#34445b;text-anchor:middle;paint-order:stroke;stroke:#fbfcfe;stroke-width:4px;stroke-linejoin:round;pointer-events:none}.node-name{font-size:18px;line-height:1.35;margin:5px 0 12px}.badge{display:inline-block;border-radius:99px;padding:4px 9px;background:#f0f3f8;color:#465970;font-size:11px;margin:0 5px 5px 0}.meta{display:grid;grid-template-columns:96px 1fr;gap:9px;font-size:12px;margin:16px 0}.meta dt{color:#77869a}.meta dd{margin:0;font-weight:600}.section-title{font-weight:700;font-size:13px;margin:20px 0 9px}.relation{border:1px solid #e9edf2;background:#fff;border-radius:8px;padding:9px 10px;width:100%;text-align:left;margin-bottom:6px;color:#34445b;font-size:12px}.relation:hover{border-color:#d89536;background:#fffaf3}.relation small{display:block;color:#9a641d;font-size:10px;font-weight:700;margin-bottom:3px}.preview{font-size:12px;line-height:1.6;color:#465970;white-space:pre-wrap;max-height:240px;overflow:auto;background:#f8fafc;border:1px solid #e8edf4;border-radius:8px;padding:11px}.empty{color:#77869a;font-size:13px;padding:16px 4px}.note{font-size:11px;color:#77869a;margin-top:12px}@media(max-width:1100px){.workspace{grid-template-columns:minmax(400px,1fr) 310px}}@media(max-width:700px){header{padding:0 15px}.workspace{display:flex;flex-direction:column;height:auto;min-height:0}.panel{max-height:320px}.canvas-card{height:580px}.detail-panel{max-height:none}}
#graph{background-color:#fff;background-image:linear-gradient(#d9e0e866 1px,transparent 1px),linear-gradient(90deg,#d9e0e866 1px,transparent 1px),linear-gradient(#c5ced777 1px,transparent 1px),linear-gradient(90deg,#c5ced777 1px,transparent 1px);background-size:20px 20px,20px 20px,100px 100px,100px 100px}.graph-edge{opacity:.7;stroke-width:1.8}.graph-edge.highlight{opacity:1;stroke-width:2.8}.graph-node circle{filter:none;stroke-width:2.5}.graph-node.active circle,.graph-node.active rect,.graph-node.active path{stroke:#263244;stroke-width:4}.graph-label{font-size:12px;stroke:#fff;stroke-width:5px}.edge-text{font-size:10px;font-weight:700;fill:#52647b;text-anchor:middle;paint-order:stroke;stroke:#fff;stroke-width:5px;stroke-linejoin:round;pointer-events:none}.edge-text.dim{opacity:.13}.edge-text.highlight{fill:#8c530c;font-size:11px}
.graph-label{font-size:14px;font-weight:700;stroke:none;fill:#25364d}.graph-kind{font-size:11px;fill:#64748b;text-anchor:middle;pointer-events:none}.graph-node.dim{opacity:.28}.graph-edge.dim{opacity:.12}
.graph-node{touch-action:none}.graph-node.active{opacity:1;filter:drop-shadow(0 0 10px #d89536aa)}.graph-node.active>circle,.graph-node.active>rect,.graph-node.active>path{stroke:#a35b10!important;stroke-width:6!important}.graph-node.connected{opacity:1}.graph-node.dim{opacity:.12}.graph-edge.highlight{stroke:#a35b10!important;stroke-width:4;opacity:1}.graph-edge.dim{opacity:.04}.edge-text.dim{opacity:.04}
</style>
</head>
<body>
<header><div><h1>Bản đồ tri thức</h1><div id="stats" class="summary">Đang tải dữ liệu…</div></div><a class="back" href="/admin/knowledge-documents">← Quay về tài liệu tri thức</a></header>
<div class="workspace">
<section class="canvas-card"><div class="canvas-head"><div><h2 id="graph-title">Mạng tri thức liên kết</h2><div id="graph-subtitle" class="sub">Nhiều tài liệu cùng chia sẻ chủ đề và khái niệm</div></div><div class="canvas-actions"><button id="zoom-out" class="small-btn" title="Thu nhỏ">−</button><button id="reset" class="small-btn" title="Về giữa">Đặt lại</button><button id="zoom-in" class="small-btn" title="Phóng to">+</button></div></div><svg id="graph" role="img" aria-label="Sơ đồ mạng các tài liệu, thực thể và quan hệ"></svg><div class="canvas-foot"><span><i class="swatch" style="background:#d49520"></i>Tài liệu</span><span><i class="swatch" style="background:#718fd0"></i>Khái niệm</span><span><i class="swatch" style="background:#9a7ad0"></i>Phòng ban</span><span><i class="swatch" style="background:#49ad9b"></i>Chủ đề</span><span><i class="swatch" style="background:#e98c88"></i>Thẻ</span><span class="muted">Kéo nút để sắp xếp · Chọn để xem chi tiết · Nhấp đúp để mở cụm</span></div></section>
<aside class="panel detail-panel"><h2>Khám phá tri thức</h2><input id="search" class="search" type="search" placeholder="Tìm theo tiêu đề hoặc mã…" autocomplete="off"><div id="result-count" class="result-count"></div><div id="results" class="list" style="max-height:190px"></div><hr style="border:0;border-top:1px solid #edf0f4;margin:18px 0"><div class="eyebrow">Chi tiết nút</div><div id="detail" class="empty">Chọn một nút trên sơ đồ để xem thuộc tính và quan hệ.</div></aside></div>
<script>
const colors={document:'#d49520',concept:'#718fd0',department:'#9a7ad0',taxonomy:'#49ad9b',tag:'#e98c88'};
const typeNames={document:'Tài liệu',concept:'Khái niệm',department:'Phòng ban',taxonomy:'Chủ đề',tag:'Thẻ'};
const svg=document.querySelector('#graph');
const namespace='http://www.w3.org/2000/svg';
let nodes=[],edges=[],nodeById=new Map(),adjacency=new Map(),focusId='',selectedId='',visibleIds=new Set(),scale=1,panX=0,panY=0,drag=null;const pointers=new Map();let pinchDistance=0;const nodePositions=new Map();let nodeDrag=null,blockClick=false;
function svgElement(tag,attributes={}){const item=document.createElementNS(namespace,tag);for(const [name,value] of Object.entries(attributes))item.setAttribute(name,value);return item}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function shorten(value,length=25){const text=String(value||'');return text.length>length?text.slice(0,length-1)+'…':text}
function neighbors(id){return adjacency.get(id)||[]}
function documentNeighbors(id){return neighbors(id).map(item=>item.other).filter(other=>nodeById.get(other)?.type==='document')}
function chooseCluster(seed){
  const documents=[seed],seen=new Set(documents),queue=[seed];
  while(queue.length&&documents.length<16){const current=queue.shift();for(const next of documentNeighbors(current)){if(!seen.has(next)){seen.add(next);documents.push(next);queue.push(next)}if(documents.length>=16)break}}
  const extra=[];const counts={department:0,taxonomy:0,concept:0,tag:0};
  for(const doc of documents){for(const {other} of neighbors(doc)){const kind=nodeById.get(other)?.type;if(kind&&kind!=='document'&&!seen.has(other)&&counts[kind]<(kind==='concept'?9:kind==='tag'?3:kind==='department'?3:2)){seen.add(other);extra.push(other);counts[kind]++}}}
  return new Set([...documents,...extra]);
}
function layout(ids){
 const documents=[...ids].filter(id=>nodeById.get(id)?.type==='document');
 const concepts=[...ids].filter(id=>nodeById.get(id)?.type==='concept');
 const other=[...ids].filter(id=>!['document','concept'].includes(nodeById.get(id)?.type));
 const positions=new Map();
 documents.forEach((id,index)=>{const angle=-Math.PI/2+index*2*Math.PI/documents.length;positions.set(id,{x:Math.cos(angle)*555,y:Math.sin(angle)*400})});
 concepts.forEach((id,index)=>{const angle=-Math.PI/2+(index+.5)*2*Math.PI/concepts.length;positions.set(id,{x:Math.cos(angle)*790,y:Math.sin(angle)*640})});
 other.forEach((id,index)=>{const angle=-Math.PI/2+(index+.3)*2*Math.PI/other.length;positions.set(id,{x:Math.cos(angle)*830,y:Math.sin(angle)*690})});
 for(const [id,point] of nodePositions)if(positions.has(id))positions.set(id,point);
 return positions;
}
function displayEdges(ids){
 const visible=edges.filter(edge=>ids.has(edge.source)&&ids.has(edge.target));
 const documentLinks=visible.filter(edge=>edge.relation==='LIÊN_QUAN');
 const remaining=visible.filter(edge=>edge.relation!=='LIÊN_QUAN');
 const seen=new Set(),selected=[];
 for(const edge of documentLinks){const pair=[edge.source,edge.target].sort().join('|');if(!seen.has(pair)){seen.add(pair);selected.push(edge)}if(selected.length>=32)break}
 const perNode=new Map();
 for(const edge of remaining){const count=perNode.get(edge.target)||0;if(count>=2)continue;selected.push(edge);perNode.set(edge.target,count+1);if(selected.length>=55)break}
 return selected;
}
function setView(){svg.setAttribute('viewBox',`${-950/scale-panX} ${-760/scale-panY} ${1900/scale} ${1520/scale}`)}
function draw(){
 visibleIds=chooseCluster(focusId);const visibleEdges=displayEdges(visibleIds);const positions=layout(visibleIds);svg.replaceChildren();
 const defs=svgElement('defs'),marker=svgElement('marker',{id:'arrow',viewBox:'0 0 10 10',refX:'8',refY:'5',markerWidth:'6',markerHeight:'6',orient:'auto-start-reverse'});marker.append(svgElement('path',{d:'M 0 0 L 10 5 L 0 10 z',fill:'#8292a5'}));defs.append(marker);svg.append(defs);
 const edgeLayer=svgElement('g'),labelLayer=svgElement('g'),nodeLayer=svgElement('g');svg.append(edgeLayer,labelLayer,nodeLayer);
 const degree=new Map([...visibleIds].map(id=>[id,visibleEdges.filter(edge=>edge.source===id||edge.target===id).length]));
 for(const edge of visibleEdges){
  const from=positions.get(edge.source),to=positions.get(edge.target),dx=to.x-from.x,dy=to.y-from.y,distance=Math.max(1,Math.hypot(dx,dy));
  const startRadius=nodeById.get(edge.source)?.type==='document'?70:62,endRadius=nodeById.get(edge.target)?.type==='document'?77:69;
  const x1=from.x+dx/distance*startRadius,y1=from.y+dy/distance*startRadius,x2=to.x-dx/distance*endRadius,y2=to.y-dy/distance*endRadius;
  edgeLayer.append(svgElement('line',{x1,y1,x2,y2,stroke:edge.relation==='LIÊN_QUAN'?'#bb8540':'#8798ab',class:'graph-edge','data-source':edge.source,'data-target':edge.target,'marker-end':'url(#arrow)'}));
  if(edge.relation!=='LIÊN_QUAN'&&['SỞ_HỮU','PHÂN_LOẠI'].includes(edge.relation)){const label=svgElement('text',{x:(x1+x2)/2,y:(y1+y2)/2-6,class:'edge-text','data-source':edge.source,'data-target':edge.target});label.textContent=edge.relation.replaceAll('_',' ').toLocaleLowerCase('vi');labelLayer.append(label)}
 }
 for(const id of visibleIds){
  const node=nodeById.get(id),point=positions.get(id),radius=node.type==='document'?66:58;
  const group=svgElement('g',{class:'graph-node','data-id':id,tabindex:'0',role:'button','aria-label':node.name});
  if(node.type==='taxonomy')group.append(svgElement('path',{d:`M ${point.x-67} ${point.y} l 33 -55 h 68 l 33 55 l -33 55 h -68 z`,fill:'#e5f5f0',stroke:colors[node.type],'stroke-width':3}));
  else if(node.type==='tag')group.append(svgElement('rect',{x:point.x-68,y:point.y-46,width:136,height:92,rx:14,fill:'#fff0ef',stroke:colors[node.type],'stroke-width':3}));
  else group.append(svgElement('circle',{cx:point.x,cy:point.y,r:radius,fill:node.type==='document'?'#fff4db':node.type==='concept'?'#e8f0ff':'#f0eafb',stroke:colors[node.type],'stroke-width':3}));
  const caption=svgElement('text',{x:point.x,y:point.y+4,class:'graph-label'});
  const value=node.type==='document'?(node.short_title||node.name):node.name;
  const words=String(value||'').split(' '),lines=[''];
  for(const word of words){const last=lines.length-1;if((lines[last]+' '+word).trim().length>17&&lines[last]&&lines.length<2)lines.push(word);else lines[last]=(lines[last]+' '+word).trim()}
  lines.forEach((line,index)=>{const span=svgElement('tspan',{x:point.x,dy:index===0?0:19});span.textContent=shorten(line,20);caption.append(span)});group.append(caption);
  if(node.type==='document'){const code=svgElement('text',{x:point.x,y:point.y-32,class:'graph-kind'});code.textContent=node.code;group.append(code)}
  if((degree.get(id)||0)>4){group.append(svgElement('circle',{cx:point.x+radius-3,cy:point.y-radius+4,r:16,fill:'#334155'}));const count=svgElement('text',{x:point.x+radius-3,y:point.y-radius+9,'text-anchor':'middle',fill:'#fff','font-size':'13','font-weight':'700'});count.textContent=degree.get(id);group.append(count)}
  const title=svgElement('title');title.textContent=node.name;group.append(title);group.addEventListener('click',()=>{if(blockClick){blockClick=false;return}select(id)});group.addEventListener('dblclick',()=>openCluster(id));group.addEventListener('keydown',event=>{if(event.key==='Enter')select(id)});nodeLayer.append(group)
 }
 document.querySelector('#graph-title').textContent='Mạng tri thức liên kết';document.querySelector('#graph-subtitle').textContent=`${[...visibleIds].filter(id=>nodeById.get(id)?.type==='document').length} tài liệu · ${visibleIds.size} nút · ${visibleEdges.length} quan hệ trong cụm`;setView();highlight();
}
function highlight(){
 const activeEdges=[...svg.querySelectorAll('.graph-edge')].filter(edge=>selectedId&&(edge.dataset.source===selectedId||edge.dataset.target===selectedId));
 const connected=new Set([selectedId]);for(const edge of activeEdges){connected.add(edge.dataset.source);connected.add(edge.dataset.target)}
 svg.querySelectorAll('.graph-node').forEach(group=>{const id=group.dataset.id;group.classList.toggle('active',id===selectedId);group.classList.toggle('connected',id!==selectedId&&connected.has(id));group.classList.toggle('dim',Boolean(selectedId)&&!connected.has(id))});
 svg.querySelectorAll('.graph-edge, .edge-text').forEach(item=>{const active=selectedId&&(item.dataset.source===selectedId||item.dataset.target===selectedId);item.classList.toggle('highlight',Boolean(active));item.classList.toggle('dim',Boolean(selectedId)&&!active)});
 for(const edge of activeEdges)edge.parentNode.append(edge);
 const selected=svg.querySelector('.graph-node.active');if(selected)selected.parentNode.append(selected);
}
function openCluster(id){const node=nodeById.get(id);let documentId=id;if(node?.type!=='document')documentId=neighbors(id).map(item=>item.other).find(other=>nodeById.get(other)?.type==='document');if(!documentId)return;focusId=documentId;nodePositions.clear();scale=1;panX=0;panY=0;draw();select(id)}
function select(id){const node=nodeById.get(id);if(!node)return;selectedId=id;highlight();const related=neighbors(id).filter(item=>nodeById.has(item.other));const connectedDocs=related.filter(item=>nodeById.get(item.other)?.type==='document');const edgeGroups=new Map();for(const item of related){if(!edgeGroups.has(item.edge.relation))edgeGroups.set(item.edge.relation,[]);edgeGroups.get(item.edge.relation).push(item)}
 let html=`<h2 class="node-name">${escapeHtml(node.name)}</h2><span class="badge">${typeNames[node.type]||escapeHtml(node.type)}</span>`;
 if(node.type==='document')html+=`<dl class="meta"><dt>Mã</dt><dd>${escapeHtml(node.code)}</dd><dt>Loại</dt><dd>${escapeHtml(node.document_type)}</dd><dt>Người đăng</dt><dd>${escapeHtml(node.poster||'Chưa có thông tin')}</dd><dt>Phòng ban</dt><dd>${escapeHtml(node.department)}</dd><dt>Phiên bản</dt><dd>${escapeHtml(node.version)}</dd><dt>Hiệu lực</dt><dd>${escapeHtml(node.effective_date)}</dd><dt>Rà soát</dt><dd>${escapeHtml(node.review_date)}</dd><dt>Phân loại</dt><dd>${escapeHtml(node.classification)}</dd><dt>Phụ trách</dt><dd>${escapeHtml(node.owner)}</dd></dl>`;
 if(node.type==='document'&&node.managed_document_id)html+=`<p><a class="back" href="/admin/knowledge-documents/${encodeURIComponent(node.managed_document_id)}/file?download=1">Tải tệp gốc được quản lý</a></p>`;
 if(node.summary)html+=`<p>${escapeHtml(node.summary)}</p>`;
 html+=`<div class="section-title">Quan hệ (${related.length})</div>`;
 for(const [relation,items] of edgeGroups){const shown=items.filter(item=>visibleIds.has(item.other)).slice(0,5);for(const item of shown){const other=nodeById.get(item.other);html+=`<button class="relation" data-id="${escapeHtml(other.id)}"><small>${escapeHtml(relation.replaceAll('_',' '))} · ${escapeHtml(typeNames[other.type]||other.type)}</small>${escapeHtml(shorten(other.name,55))}</button>`}}
 if(connectedDocs.length>0&&!connectedDocs.some(item=>visibleIds.has(item.other)))html+='<div class="note">Nhấp đúp vào nút trên sơ đồ để khám phá cụm lân cận.</div>';
 if(node.content)html+=`<details style="margin-top:15px"><summary class="section-title">Nội dung trích xuất</summary><div class="preview">${escapeHtml(node.content.slice(0,5500))}</div></details>`;
 if(node.type==='document')html+='<button id="recenter" class="small-btn" style="margin-top:14px">Xem cụm quanh tài liệu này</button>';
 document.querySelector('#detail').innerHTML=html;document.querySelectorAll('.relation').forEach(button=>button.onclick=()=>{const next=button.dataset.id;if(!visibleIds.has(next))openCluster(next);else select(next)});const recenter=document.querySelector('#recenter');if(recenter)recenter.onclick=()=>openCluster(id);renderResults()}
function renderResults(){const query=document.querySelector('#search').value.trim().toLocaleLowerCase('vi');const results=nodes.filter(node=>node.type==='document'&&(!query||(node.name+' '+node.code).toLocaleLowerCase('vi').includes(query)));document.querySelector('#result-count').textContent=`${results.length} tài liệu${query?' phù hợp':''}`;document.querySelector('#results').innerHTML=results.slice(0,30).map(node=>`<button class="result ${node.id===selectedId?'active':''}" data-id="${escapeHtml(node.id)}"><strong>${escapeHtml(node.code)}</strong><span>${escapeHtml(node.name)}</span></button>`).join('')+(results.length>30?'<div class="note">Nhập thêm từ khóa để thu hẹp kết quả.</div>':'');document.querySelectorAll('.result').forEach(button=>button.onclick=()=>openCluster(button.dataset.id))}
function zoomAt(factor,clientX,clientY){
 const box=svg.getBoundingClientRect(),ratioX=(clientX-box.left)/box.width-.5,ratioY=(clientY-box.top)/box.height-.5;
 const next=Math.max(.55,Math.min(4,scale*factor));
 panX+=ratioX*1900*(1/next-1/scale);panY+=ratioY*1520*(1/next-1/scale);
 scale=next;setView();
}
svg.addEventListener('pointerdown',event=>{
 pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});
 const target=event.target.closest('.graph-node');
 if(target&&pointers.size===1){nodeDrag={id:target.dataset.id,x:event.clientX,y:event.clientY,moved:false};return}
 if(pointers.size===2){const values=[...pointers.values()];pinchDistance=Math.hypot(values[0].x-values[1].x,values[0].y-values[1].y);drag=null;nodeDrag=null;svg.setPointerCapture(event.pointerId);return}
 drag={x:event.clientX,y:event.clientY};svg.setPointerCapture(event.pointerId);svg.classList.add('dragging')
});
svg.addEventListener('pointermove',event=>{
 if(!pointers.has(event.pointerId))return;
 pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});
 if(pointers.size===2){const values=[...pointers.values()],distance=Math.hypot(values[0].x-values[1].x,values[0].y-values[1].y);if(pinchDistance)zoomAt(distance/pinchDistance,(values[0].x+values[1].x)/2,(values[0].y+values[1].y)/2);pinchDistance=distance;return}
 if(nodeDrag){
  const dx=event.clientX-nodeDrag.x,dy=event.clientY-nodeDrag.y;
  if(!nodeDrag.moved&&Math.hypot(dx,dy)<4)return;
  if(!nodeDrag.moved){nodeDrag.moved=true;svg.setPointerCapture(event.pointerId);svg.classList.add('dragging')}
  const box=svg.getBoundingClientRect(),base=layout(visibleIds).get(nodeDrag.id);
  nodePositions.set(nodeDrag.id,{x:base.x+dx*1900/(box.width*scale),y:base.y+dy*1520/(box.height*scale)});
  nodeDrag.x=event.clientX;nodeDrag.y=event.clientY;draw();return
 }
 if(!drag)return;const box=svg.getBoundingClientRect();panX+=(event.clientX-drag.x)*1900/(box.width*scale);panY+=(event.clientY-drag.y)*1520/(box.height*scale);drag={x:event.clientX,y:event.clientY};setView()
});
function stopPointer(event){
 if(nodeDrag?.moved){blockClick=true;setTimeout(()=>{blockClick=false},80)}
 pointers.delete(event.pointerId);nodeDrag=null;drag=null;pinchDistance=0;svg.classList.remove('dragging')
}
svg.addEventListener('pointerup',stopPointer);svg.addEventListener('pointercancel',stopPointer);
svg.addEventListener('wheel',event=>{event.preventDefault();zoomAt(Math.exp(-event.deltaY*(event.ctrlKey?.012:.0015)),event.clientX,event.clientY)},{passive:false});
document.querySelector('#zoom-in').onclick=()=>{const box=svg.getBoundingClientRect();zoomAt(1.3,box.left+box.width/2,box.top+box.height/2)};
document.querySelector('#zoom-out').onclick=()=>{const box=svg.getBoundingClientRect();zoomAt(1/1.3,box.left+box.width/2,box.top+box.height/2)};
document.querySelector('#reset').onclick=()=>{scale=1;panX=0;panY=0;setView()};
document.querySelector('#search').addEventListener('input',renderResults);
fetch('/admin/knowledge-graph-demo/data',{cache:'no-store'}).then(response=>{if(!response.ok)throw Error('Không tải được dữ liệu');return response.json()}).then(data=>{nodes=data.nodes;edges=data.edges;nodeById=new Map(nodes.map(node=>[node.id,node]));for(const edge of edges){for(const [id,other] of [[edge.source,edge.target],[edge.target,edge.source]]){if(!adjacency.has(id))adjacency.set(id,[]);adjacency.get(id).push({other,edge})}}document.querySelector('#stats').textContent=`${nodes.filter(node=>node.type==='document').length} tài liệu · ${nodes.length} nút · ${edges.length} quan hệ`;focusId=nodeById.has('document:'+new URLSearchParams(location.search).get('document'))?'document:'+new URLSearchParams(location.search).get('document'):'document:KB-GOV-001';draw();select(focusId);selectedId='';highlight()}).catch(error=>document.querySelector('#stats').textContent=error.message);
</script>
</body></html>
